function getAllTopics() {
  const topics = new Set(DEFAULT_IELTS_WORDS.map(w => w.topic));
  return Array.from(topics).filter(Boolean).sort();
}

function getAllBands() {
  return ['4.0', '4.5', '5.0', '5.5', '6.0', '6.5', '7.0', '7.5', '8.0', '8.5', '9.0'];
}

